"use client";

import { FormEvent, useState } from "react";
import { FiLoader } from "react-icons/fi";

import { saveAuthToken } from "@/lib/auth";
import { graphqlRequest } from "@/lib/graphql";
import { InputComponent } from "../Input/page";
import styles from "./signincomponent.module.css";

function SignInComponent({ pageTitle }: { pageTitle: string }) {
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  async function signIn(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting) return;
    const data = new FormData(event.currentTarget);
    const login = String(data.get("login") ?? "").trim();
    const password = String(data.get("password") ?? "");
    if (!login || !password) return;

    setSubmitting(true);
    setError("");
    try {
      const result = await graphqlRequest<{ signIn: { token: string } }>(
        `mutation SignIn($data: SignInInput!) {
          signIn(data: $data) { token }
        }`,
        { data: { login, password } },
      );
      saveAuthToken(result.signIn.token);

      const next = new URLSearchParams(window.location.search).get("next");
      window.location.assign(next?.startsWith("/") ? next : "/");
    } catch (signInError) {
      setError(signInError instanceof Error ? signInError.message : "Não foi possível entrar.");
      setSubmitting(false);
    }
  }

  return (
    <section>
      <div className={styles.signInBox}>
        <h1 className={styles.signInTitle}>{pageTitle}</h1>

        <form autoComplete="on" onSubmit={signIn}>
          <InputComponent
            inputLabel="Username ou email"
            inputType="text"
            inputName="login"
            inputPlaceholder="Digite seu username ou email…"
            required
          />

          <InputComponent
            inputLabel="Senha"
            inputType="password"
            inputName="password"
            inputPlaceholder="Digite sua senha…"
            required
          />

          {error && <p className={styles.errorMessage} role="alert">{error}</p>}
          <button className={styles.signInBtn} disabled={submitting}>
            {submitting && <FiLoader className={styles.spinner} aria-hidden="true" />}
            {submitting ? "Entrando…" : "Entrar"}
          </button>
        </form>
      </div>
    </section>
  );
}

export { SignInComponent };
